def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # The stamp is the connected non-background object containing color 2.
    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg}
    stamp = None
    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if (nr, nc) in remaining:
                    remaining.remove((nr, nc))
                    comp.add((nr, nc))
                    stack.append((nr, nc))
        if any(grid[r][c] == 2 for r, c in comp):
            stamp = comp
            break

    if not stamp:
        return [row[:] for row in grid]

    stamp_colors = {grid[r][c] for r, c in stamp}
    marker_colors = {v for v in counts if v != bg and v not in stamp_colors}
    if not marker_colors:
        return [row[:] for row in grid]
    marker = max(marker_colors, key=lambda v: counts[v])
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == marker]

    minr = min(r for r, c in stamp)
    maxr = max(r for r, c in stamp)
    minc = min(c for r, c in stamp)
    maxc = max(c for r, c in stamp)
    ar, ac = (minr + maxr) // 2, (minc + maxc) // 2

    out = [row[:] for row in grid]
    for r, c in markers:
        out[r][c] = bg
        for sr, sc in stamp:
            rr, cc = r + sr - ar, c + sc - ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = grid[sr][sc]
    return out
